import json, pathlib, collections, hashlib, html, re
ROOT=pathlib.Path(__file__).resolve().parents[1]
def read(name): return json.loads((ROOT/name).read_text())
def save(name,data): (ROOT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2))
pages=read('inventory/pages.json'); products=read('inventory/products.json')
dealers={}
for row in read('inventory/dealers-initial-pages.json'):
    key=row.get('id') or row.get('name','')+'|'+row.get('address','')
    if key not in dealers:
        dealers[key]={k:v for k,v in row.items() if k not in ['source_page','exposition']}
        dealers[key].update(source_pages=[],exposition=[])
    dest=dealers[key]
    if row['source_page'] not in dest['source_pages']: dest['source_pages'].append(row['source_page'])
    for ex in row.get('exposition') or []:
        if ex not in dest['exposition']:dest['exposition'].append(ex)
save('inventory/dealers.json',list(dealers.values()))

issues=[]
def issue(priority,title,evidence,impact,proposal,source,kind='Наблюдение'):
    issues.append(dict(id='UX-%02d'%(len(issues)+1),priority=priority,title=title,evidence=evidence,impact=impact,proposal=proposal,source=source,kind=kind))
issue('P1','Поиск находит семейство, но не показывает искомое исполнение','Поиск 1051201M возвращает Aria с ценой «от 790 000», хотя проверенное исполнение S-Stone стоит 890 000.','Профессионал может принять минимальную цену семейства за цену артикула.','Точное совпадение SKU первым; материал, поверхность, цена и наличие именно этого SKU.','../evidence/search-sku.jpg')
issue('P1','Ошибочная раскладка не исправляется','1051201Ь вместо 1051201M даёт пустой результат. Проверен один запрос.','Потеря найденного по документу артикула при вводе с русской клавиатуры.','Нормализовать артикулы; предлагать исправление раскладки и похожие коды.','../evidence/search-sku-ru-layout.jpg')
issue('P1','Сроки требуют единой трактовки','FAQ говорит о 10–30 рабочих днях; PDF сроков использует календарные сроки по классам, карточка Aria — «до 30 дней».','Нельзя достоверно рассчитать обещанную дату из свободного текста.','Срок и тип календаря хранить по исполнению; отдельно производство, готовность и доставка.','../evidence/production-terms-1.jpg')
issue('P1','Устаревшие адреса остаются в индексируемой структуре','В обходе 35 ответов 404, включая прежние варианты OASI, ONDA, DOMINO и относительный /www.konzept.ru.','Потеря связи между контентом, товаром и документами при миграции.','Таблица старый URL → сущность/новый маршрут; восстановить или исключить устаревшее.','../inventory/pages.json')
issue('P1','Часть технических файлов недоступна','Среди проверенных прямых ресурсов есть 404 у инструкции мебели SALINI ES и чертежа TOUCH 600.','На этапе монтажа отсутствующий документ важнее декоративной ошибки.','Контроль доступности файлов, версия, привязка к SKU и замена отсутствующего документа.','../inventory/downloads.json')
issue('P1','Остатки представлены датированным файлом','Публичный XLSX содержит дату прайса 05.10.2026 23:30:00 и предупреждение об уточнении наличия.','Скачанный остаток нельзя использовать как подтверждение резерва.','Показывать время обновления и склад; подтверждать доступность при заявке/резерве.','../assets/documents/f85846928560-Salini_Stock_XLSX.xlsx')
issue('P1','Расчёт кастомных изделий включает ручной перенос цены','COSTA: D6 заполняется вручную из листа «ЦЕНЫ». ONDA: C12 вручную; текст A11 требует учесть RAL +50%.','Нельзя просто перенести форму и ожидать автоматического расчёта без ошибок.','Утвердить правила и прайс-версию; серверный расчёт со структурой доплат и проверкой граничных размеров.','../inventory/workbook-structure.json')
issue('P2','Технический контекст распределён по разным каналам','PDP, паспорта, чертежи, XLSX и Яндекс Диск содержат разные части данных.','Пользователь переключается между файлами и теряет выбранное исполнение.','Единая карточка конфигурации с документами и сохранением в проект.','https://salini-srl.com/vanny/otdelnostoyashchie/aria/')
issue('P2','Начало карточки не даёт короткой сводки','На мобильном первом экране Aria много описания; размеры и рабочие детали ниже.','Сравнение вариантов требует лишней прокрутки.','Сразу под фото показать габариты, материал, цену, срок; описания раскрывать по запросу.','../evidence/aria-mobile-top.jpg')
issue('P2','Плотная мобильная навигация','Иконки нескольких каналов связи в шапке, меню, корзина и поиск; PDP имеет горизонтальные якоря.','Несколько конкурирующих способов перехода и действий.','Устойчивые системные разделы и одна главная кнопка в контексте экрана.','../evidence/catalog-mobile.jpg')
